<section class="grid"><?php foreach ($tasks as $task): ?><article class="card"><h2><?= esc($task['title']) ?></h2><p><?= esc($task['description']) ?></p><p>Date: <?= esc($task['task_date']) ?></p><?php if (session('user_id')): ?><p class="actions"><a href="<?= site_url('tasks/' . $task['id'] . '/edit') ?>">Edit</a><form method="post" action="<?= site_url('tasks/' . $task['id'] . '/delete') ?>"><?= csrf_field() ?><button class="danger" type="submit">Archive</button></form></p><?php endif; ?></article><?php endforeach; ?></section>
